import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { CheckCircle, Image, XCircle } from 'lucide-react';
import type React from 'react';
import { useCallback, useState } from 'react';
import { apiClient } from '@/api/client';
import { useNotification } from '@/components/notification';

interface ImageOptimizationSettings {
  enabled: boolean;
}

interface ImageOptimizationResponse {
  enabled: boolean;
  success: boolean;
  message?: string;
}

const fetchImageOptimizationSettings =
  (): Promise<ImageOptimizationSettings> => {
    return apiClient.get('/settings/image-optimization');
  };

const saveImageOptimizationSettings = (
  settings: ImageOptimizationSettings
): Promise<ImageOptimizationResponse> => {
  return apiClient.post('/settings/image-optimization', settings);
};

export const ImageOptimization: React.FC = () => {
  const { notify } = useNotification();
  const queryClient = useQueryClient();
  const [saveTimeout, setSaveTimeout] = useState<ReturnType<
    typeof setTimeout
  > | null>(null);

  // 获取图片优化设置
  const { data: settings, isLoading } = useQuery({
    queryKey: ['image-optimization-settings'],
    queryFn: fetchImageOptimizationSettings,
  });

  // 使用 API 返回值，加载中时默认 false（关闭）
  const enabled = settings?.enabled ?? false;

  // 保存设置 mutation
  const saveMutation = useMutation({
    mutationFn: saveImageOptimizationSettings,
    onSuccess: (response) => {
      queryClient.invalidateQueries({
        queryKey: ['image-optimization-settings'],
      });
      notify('success', response.message || '设置已保存', 2000);
    },
    onError: (error) => {
      notify('error', `保存失败: ${(error as Error).message}`);
      // 重新获取真实状态
      queryClient.invalidateQueries({
        queryKey: ['image-optimization-settings'],
      });
    },
  });

  // 防抖保存
  const debouncedSave = useCallback(
    (newEnabled: boolean) => {
      if (saveTimeout) {
        clearTimeout(saveTimeout);
      }
      const timeout = setTimeout(() => {
        saveMutation.mutate({ enabled: newEnabled });
      }, 300);
      setSaveTimeout(timeout);
    },
    [saveTimeout, saveMutation]
  );

  // 切换开关
  const handleToggle = () => {
    if (isLoading) {
      return; // 加载中不允许操作
    }
    const newValue = !enabled;
    // 乐观更新：先更新缓存，再发请求
    queryClient.setQueryData(['image-optimization-settings'], {
      enabled: newValue,
    });
    debouncedSave(newValue);
  };

  // 计算开关按钮样式
  const getToggleClass = () => {
    if (isLoading) {
      return 'cursor-wait bg-gray-300';
    }
    return enabled ? 'bg-green-500' : 'bg-gray-200';
  };

  return (
    <div className="space-y-6">
      {/* 标题 */}
      <div className="flex items-center gap-3">
        <Image className="h-6 w-6 text-gray-600" />
        <h2 className="font-semibold text-gray-900 text-lg">图片优化</h2>
      </div>

      {/* 状态卡片 */}
      {enabled ? (
        <div className="rounded-lg border border-green-200 bg-green-50 p-6">
          <div className="mb-3 flex items-center gap-3">
            <CheckCircle className="h-6 w-6 text-green-600" />
            <h3 className="font-semibold text-green-900 text-lg">
              图片优化已开启
            </h3>
          </div>
          <p className="text-green-700 text-sm">
            页面保存时会自动生成 WebP 格式的响应式图片标签，提升加载速度。
          </p>
        </div>
      ) : (
        <div className="rounded-lg border border-yellow-200 bg-yellow-50 p-6">
          <div className="mb-3 flex items-center gap-3">
            <XCircle className="h-6 w-6 text-yellow-600" />
            <h3 className="font-semibold text-lg text-yellow-900">
              图片优化已关闭
            </h3>
          </div>
          <p className="text-sm text-yellow-700">
            页面将直接使用原始图片标签，不生成 WebP 响应式图片。
          </p>
        </div>
      )}

      {/* 开关 */}
      <div className="flex items-center justify-between rounded-lg border border-gray-200 bg-white p-4">
        <div>
          <div className="font-medium text-gray-900">启用图片优化</div>
          <div className="text-gray-500 text-sm">
            保存页面时自动生成 WebP 响应式图片
          </div>
        </div>
        <button
          aria-checked={enabled}
          className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${getToggleClass()}`}
          disabled={isLoading}
          onClick={handleToggle}
          role="switch"
          type="button"
        >
          <span
            className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
              enabled ? 'translate-x-6' : 'translate-x-1'
            }`}
          />
        </button>
      </div>
    </div>
  );
};
