import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { CheckCircle, XCircle } from 'lucide-react';
import type React from 'react';
import { useCallback, useState } from 'react';
import { apiClient } from '@/api/client';
import { useNotification } from '@/components/notification';
import { useLocalCompiler } from '@/settings/hooks/use-local-compiler';

interface SpeedSettings {
  enabled: boolean;
}

interface SpeedSettingsResponse {
  enabled: boolean;
  success: boolean;
  should_compile?: boolean;
  warning?: string;
}

const fetchSpeedSettings = (): Promise<SpeedSettings> => {
  return apiClient.get('/settings/speed');
};

const saveSpeedSettings = (
  settings: SpeedSettings
): Promise<SpeedSettingsResponse> => {
  return apiClient.post('/settings/speed', settings);
};

export const CSSOptimization: React.FC = () => {
  const { notify } = useNotification();
  const queryClient = useQueryClient();
  const localCompiler = useLocalCompiler();
  const [saveTimeout, setSaveTimeout] = useState<ReturnType<
    typeof setTimeout
  > | null>(null);

  // 获取速度设置
  const { data: speedSettings, isLoading } = useQuery({
    queryKey: ['speed-settings'],
    queryFn: fetchSpeedSettings,
  });

  // 使用 API 返回值，加载中时默认 false（关闭）
  const autoOptimize = speedSettings?.enabled ?? false;

  // 处理编译成功
  const handleCompileSuccess = useCallback(
    (
      hasChanged: boolean,
      stats: { compiledPages: number; compiledTemplates: number }
    ) => {
      const message = `整站速度优化完成！已优化 ${stats.compiledPages} 个页面，${stats.compiledTemplates} 个模板`;
      notify('success', message, 5000);

      if (hasChanged) {
        setTimeout(() => window.location.reload(), 1000);
      }
    },
    [notify]
  );

  // 处理编译失败
  const handleCompileError = useCallback(() => {
    const errorMsg =
      localCompiler.state.error ||
      '整站编译失败，请刷新页面重试，或联系技术支持';
    notify('error', errorMsg);
  }, [localCompiler.state.error, notify]);

  // 处理非编译情况
  const handleNoCompile = useCallback(
    (hasChanged: boolean) => {
      notify('success', '设置已保存', 2000);

      if (hasChanged) {
        setTimeout(() => window.location.reload(), 500);
      }
    },
    [notify]
  );

  // 保存设置 mutation
  const saveMutation = useMutation({
    mutationFn: saveSpeedSettings,
    onSuccess: async (response) => {
      queryClient.invalidateQueries({ queryKey: ['speed-settings'] });

      const hasChanged = !!(
        speedSettings && speedSettings.enabled !== response.enabled
      );

      // 显示警告（如果有）
      if (response.warning) {
        notify('warning', response.warning, 5000);
      }

      // 需要编译
      if (response.should_compile) {
        notify('info', '正在进行整站速度优化，请稍候...', 3000);
        const compileResult = await localCompiler.compile();

        if (compileResult) {
          handleCompileSuccess(hasChanged, compileResult.stats);
        } else {
          handleCompileError();
        }
      } else {
        handleNoCompile(hasChanged);
      }
    },
    onError: (error) => {
      notify('error', `保存失败: ${(error as Error).message}`);
      queryClient.invalidateQueries({ queryKey: ['speed-settings'] });
    },
  });

  // 防抖保存
  const debouncedSave = useCallback(
    (newAutoOptimize: boolean) => {
      if (saveTimeout) {
        clearTimeout(saveTimeout);
      }
      const timeout = setTimeout(() => {
        saveMutation.mutate({ enabled: newAutoOptimize });
      }, 300);
      setSaveTimeout(timeout);
    },
    [saveTimeout, saveMutation]
  );

  // 切换开关
  const handleToggle = () => {
    if (isLoading) {
      return; // 加载中不允许操作
    }
    const newValue = !autoOptimize;
    // 乐观更新：先更新缓存，再发请求
    queryClient.setQueryData(['speed-settings'], { enabled: newValue });
    debouncedSave(newValue);
  };

  // 计算开关按钮样式
  const getToggleClass = () => {
    if (isLoading) {
      return 'cursor-wait bg-gray-300';
    }
    return autoOptimize ? 'bg-green-500' : 'bg-gray-200';
  };

  return (
    <div className="space-y-6">
      {/* 状态卡片 */}
      {autoOptimize ? (
        <div className="rounded-lg border border-green-200 bg-green-50 p-6">
          <div className="mb-3 flex items-center gap-3">
            <CheckCircle className="h-6 w-6 text-green-600" />
            <h3 className="font-semibold text-green-900 text-lg">
              自动速度优化已开启
            </h3>
          </div>
          <p className="text-green-700 text-sm">
            保存页面或模板时会自动优化加载速度，让访客体验更流畅。
          </p>
        </div>
      ) : (
        <div className="rounded-lg border border-yellow-200 bg-yellow-50 p-6">
          <div className="mb-3 flex items-center gap-3">
            <XCircle className="h-6 w-6 text-yellow-600" />
            <h3 className="font-semibold text-lg text-yellow-900">
              自动速度优化已关闭
            </h3>
          </div>
          <p className="text-sm text-yellow-700">
            保存时不会进行速度优化。建议保持开启以获得最佳访问体验。
          </p>
        </div>
      )}

      {/* 开关 */}
      <div className="flex items-center justify-between rounded-lg border border-gray-200 bg-white p-4">
        <div>
          <div className="font-medium text-gray-900">自动速度优化</div>
          <div className="text-gray-500 text-sm">
            保存时自动优化页面加载速度
          </div>
        </div>
        <button
          aria-checked={autoOptimize}
          className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${getToggleClass()}`}
          disabled={isLoading}
          onClick={handleToggle}
          role="switch"
          type="button"
        >
          <span
            className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
              autoOptimize ? 'translate-x-6' : 'translate-x-1'
            }`}
          />
        </button>
      </div>

      {/* 建议提示 */}
      {!autoOptimize && (
        <p className="text-center text-gray-500 text-sm">
          💡 建议保持开启，让您的网站访问更快
        </p>
      )}

      {/* 编译进度 */}
      {localCompiler.state.isCompiling && (
        <div className="rounded-lg border border-blue-200 bg-blue-50 p-6">
          <div className="mb-4 flex items-center justify-between">
            <div className="font-medium text-blue-900">
              {localCompiler.state.stage === 'fetching' && '准备中...'}
              {localCompiler.state.stage === 'compiling' && '编译中...'}
              {localCompiler.state.stage === 'saving' && '保存中...'}
            </div>
            <div className="font-medium text-blue-900">
              {localCompiler.state.progress}%
            </div>
          </div>

          <div className="mb-2 h-2 w-full overflow-hidden rounded-full bg-blue-200">
            <div
              className="h-full bg-blue-600 transition-all duration-300"
              style={{ width: `${localCompiler.state.progress}%` }}
            />
          </div>

          <div className="text-blue-700 text-sm">
            {localCompiler.state.currentItem}
            {localCompiler.state.totalItems > 0 &&
              ` (${localCompiler.state.currentIndex}/${localCompiler.state.totalItems})`}
          </div>
        </div>
      )}
    </div>
  );
};
